function GetMovingColorSequence(palette, wtxIySxOCo)
    local QtkqRuZdOIHg = {}
    for step = 0, 5 do
        local kBpLVoQyEgq = step / 5
        local RqNhKNvFo = (kBpLVoQyEgq - wtxIySxOCo) % 1
        if RqNhKNvFo < 0 then RqNhKNvFo = RqNhKNvFo + 1 end
        local KoMXvoITppg = #palette - 1
        local vfsljJdb = RqNhKNvFo * KoMXvoITppg
        local SgXoqVrQ = math.floor(vfsljJdb) + 1
        local pATooHtn = vfsljJdb - (SgXoqVrQ - 1)
        local InaXRkGDwJ
        if SgXoqVrQ >= #palette then InaXRkGDwJ = palette[#palette] else InaXRkGDwJ = palette[SgXoqVrQ]:Lerp(palette[SgXoqVrQ + 1], pATooHtn) end
        do (function() table.insert(QtkqRuZdOIHg, ColorSequenceKeypoint.new(kBpLVoQyEgq, InaXRkGDwJ)) end)() end
    end
    return ColorSequence.new(QtkqRuZdOIHg)
end

